import{_ as a,o as t,c as r,a2 as c}from"./chunks/framework.F7eQ-ohH.js";const d=JSON.parse('{"title":"1.央国企笔试概述","description":"","frontmatter":{},"headers":[],"relativePath":"docs/笔试指南/1.央国企笔试概述.md","filePath":"docs/笔试指南/1.央国企笔试概述.md","lastUpdated":1788883925000}'),n={name:"docs/笔试指南/1.央国企笔试概述.md"};function o(l,e,i,h,p,s){return t(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="_1-央国企笔试概述" tabindex="-1">1.央国企笔试概述 <a class="header-anchor" href="#_1-央国企笔试概述" aria-label="Permalink to &quot;1.央国企笔试概述&quot;">​</a></h1><h2 id="哪些央国企需要笔试" tabindex="-1">哪些央国企需要笔试？ <a class="header-anchor" href="#哪些央国企需要笔试" aria-label="Permalink to &quot;哪些央国企需要笔试？&quot;">​</a></h2><p>大多数培训机构教大家培训都是针对需要笔试的央企，然而需要笔试的央国企只是少部分垄断、半垄断央企，如中国烟草、国家电网、三桶油等。 实际上，大量的央企其实没有那么严格的考试，也不会组织正式的笔试，最多让你线上填写一个性格测试或者做一个线上的笔试题，而且笔试的内容也不完全是外面培训班所培训的行测。</p><p>所以大多数培训班培训行测都是在误人子弟，并不利于应届生扩大择业的范围，增加秋招时的央国企的选择面，光去准备考试实际上是得不偿失的。 但是，既然有央企招聘的时候需要笔试，这里本熊就给大家汇总一下哪些央国企需要笔试，并附上招聘链接，大家可以自行查看笔试内容，也可以直接参考《央企手册》当中的关于笔试内容和占比的划分。</p><h3 id="哪些央国企需要笔试-——考试路线" tabindex="-1">哪些央国企需要笔试？——考试路线 <a class="header-anchor" href="#哪些央国企需要笔试-——考试路线" aria-label="Permalink to &quot;哪些央国企需要笔试？——考试路线&quot;">​</a></h3><ul><li><p>国家电网：<a href="https://zhaopin.sgcc.com.cn/sgcchr/static/unitPart.html?bullet_id=1d05b1f3d7bd437a90a6e1d14ba626d1" target="_blank" rel="noreferrer">https://zhaopin.sgcc.com.cn/sgcchr/static/unitPart.html?bullet_id=1d05b1f3d7bd437a90a6e1d14ba626d1</a></p></li><li><p>中国烟草：<a href="http://www.tobacco.gov.cn/gjyc/zpxx/list.shtml" target="_blank" rel="noreferrer">http://www.tobacco.gov.cn/gjyc/zpxx/list.shtml</a></p></li><li><p>中国石油（网站只有秋招和春招的时候才能打开）：<a href="https://zhaopin.cnpc.com.cn/index.html" target="_blank" rel="noreferrer">https://zhaopin.cnpc.com.cn/index.html</a></p></li><li><p>中国石化：<a href="http://job.sinopec.com/#/index" target="_blank" rel="noreferrer">http://job.sinopec.com/#/index</a></p></li><li><p>中国海油：<a href="https://cnooc.iguopin.com/" target="_blank" rel="noreferrer">https://cnooc.iguopin.com/</a></p></li><li><p>中国中铁（铁路局）：<a href="https://rczp.china-railway.com.cn/" target="_blank" rel="noreferrer">https://rczp.china-railway.com.cn/</a></p></li><li><p>中国铁建：<a href="https://wecruit.hotjob.cn/SU6125b2ce0dcad4106f124ff0/pb/school.html" target="_blank" rel="noreferrer">https://wecruit.hotjob.cn/SU6125b2ce0dcad4106f124ff0/pb/school.html</a></p></li><li><p>国家能源集团：<a href="https://zhaopin.chnenergy.com.cn/planSerch?kinds=3" target="_blank" rel="noreferrer">https://zhaopin.chnenergy.com.cn/planSerch?kinds=3</a></p></li><li><p>国家管网集团：<a href="https://wecruit.hotjob.cn/SU617b87702f9d247cb97cc6b7/pb/school.html" target="_blank" rel="noreferrer">https://wecruit.hotjob.cn/SU617b87702f9d247cb97cc6b7/pb/school.html</a></p></li><li><p>中粮集团：<a href="https://cofco-campus.zhaopin.com/" target="_blank" rel="noreferrer">https://cofco-campus.zhaopin.com/</a></p></li><li><p>中国农业银行：<a href="https://career.abchina.com.cn/build/index.html#/" target="_blank" rel="noreferrer">https://career.abchina.com.cn/build/index.html#/</a></p></li><li><p>中国工商银行：<a href="https://job.icbc.com.cn/pc/index.html" target="_blank" rel="noreferrer">https://job.icbc.com.cn/pc/index.html</a></p></li><li><p>中国建设银行：<a href="https://job3.ccb.com/cn/job/index.html" target="_blank" rel="noreferrer">https://job3.ccb.com/cn/job/index.html</a></p></li><li><p>中国银行：<a href="https://www.boc.cn/aboutboc/bi4/" target="_blank" rel="noreferrer">https://www.boc.cn/aboutboc/bi4/</a></p></li><li><p>中国邮政储蓄银行：<a href="https://www.psbc.com/cn/gyyc/rczp/xyzp/" target="_blank" rel="noreferrer">https://www.psbc.com/cn/gyyc/rczp/xyzp/</a></p></li><li><p>中国银行：<a href="https://www.boc.cn/aboutboc/bi4/" target="_blank" rel="noreferrer">https://www.boc.cn/aboutboc/bi4/</a></p></li></ul><h3 id="哪些央企不需要考试-——技术路线" tabindex="-1">哪些央企不需要考试？——技术路线 <a class="header-anchor" href="#哪些央企不需要考试-——技术路线" aria-label="Permalink to &quot;哪些央企不需要考试？——技术路线&quot;">​</a></h3><ul><li><p>中国五矿：<a href="https://wecruit.hotjob.cn/SU62f37858bef57c29ead8adab/pb/custom.html?parentKey=section_hide_1660130532845&amp;pageType=customize_section_hide_1660130532845#/" target="_blank" rel="noreferrer">https://wecruit.hotjob.cn/SU62f37858bef57c29ead8adab/pb/custom.html?parentKey=section_hide_1660130532845&amp;pageType=customize_section_hide_1660130532845#/</a></p></li><li><p>中国建筑：<a href="https://recruit.cscec.com/recruit#/index_nav?contract_unit=31997577&amp;company_id=1873" target="_blank" rel="noreferrer">https://recruit.cscec.com/recruit#/index_nav?contract_unit=31997577&amp;company_id=1873</a></p></li><li><p>中国电建：<a href="https://zhaopin.powerchina.cn/index" target="_blank" rel="noreferrer">https://zhaopin.powerchina.cn/index</a></p></li><li><p>中国核工业集团：<a href="https://cnnc.zhiye.com/" target="_blank" rel="noreferrer">https://cnnc.zhiye.com/</a></p></li><li><p>中国兵器装备：<a href="https://www.csgc.com.cn/" target="_blank" rel="noreferrer">https://www.csgc.com.cn/</a></p></li><li><p>中国兵器工业：<a href="http://www.norincogroup.com.cn/" target="_blank" rel="noreferrer">http://www.norincogroup.com.cn/</a></p></li><li><p>航天科技：<a href="https://www.spacechina.com/n25/index.html" target="_blank" rel="noreferrer">https://www.spacechina.com/n25/index.html</a></p></li><li><p>航天科工：<a href="http://www.casic.com.cn/" target="_blank" rel="noreferrer">http://www.casic.com.cn/</a></p></li><li><p>中航工业：<a href="https://www.avic.com.cn/" target="_blank" rel="noreferrer">https://www.avic.com.cn/</a></p></li><li><p>中国电科：<a href="https://www.cetc.com.cn/" target="_blank" rel="noreferrer">https://www.cetc.com.cn/</a></p></li><li><p>中国船舶：<a href="http://www.cssc.net.cn/" target="_blank" rel="noreferrer">http://www.cssc.net.cn/</a></p></li><li><p>中国物理工程研究院：<a href="https://zpxx.caep.cn/#/index" target="_blank" rel="noreferrer">https://zpxx.caep.cn/#/index</a></p></li></ul><p>注意，这里所说的不需要考试的央企只是针对这些集团中的大多数公司不会举行线上或者线下的考试，但是并不意味着其旗下所有央企都不会要求有笔试。 例如：中国电科集团的大多数央企都无需笔试，但是中电29所却有在线的笔试，并且根据专业的不同笔试的内容还会有所不同，所以大家需要根据具体的公司来准备。</p><h2 id="央国企的笔试内容" tabindex="-1">央国企的笔试内容？ <a class="header-anchor" href="#央国企的笔试内容" aria-label="Permalink to &quot;央国企的笔试内容？&quot;">​</a></h2><p>央国企的笔试内容不同的公司之间略有差异，但是主要分为以下三个科目：专业综合知识 + 公共基础知识 + 英语</p><h3 id="专业综合知识" tabindex="-1">专业综合知识 <a class="header-anchor" href="#专业综合知识" aria-label="Permalink to &quot;专业综合知识&quot;">​</a></h3><p>大家在学校学习的你们专业的专业课，以计算机专业为例就是《操作系统》、《数据结构》、《计算机组成原理》、《计算机网络》，对于电网来说还多一个信息新技术。 像中石油这类央企，专业综合知识是专门作为一次笔试来进行考试的，而电网、烟草的笔试则是和后面的公共基础知识结合在一起的，比例在50%～70%不等，所以这才是央国企笔试准备的重点。 准备的策略最全面的方法就是刷考研的专业课资料，但是央国企考试的专业课考试会简单非常多，所以不想刷那么难的题的话也可以买中公、粉笔等机构最专业的资料（但是他们的班就真的不建议报了）。</p><h3 id="公共基础知识-行测" tabindex="-1">公共基础知识（行测） <a class="header-anchor" href="#公共基础知识-行测" aria-label="Permalink to &quot;公共基础知识（行测）&quot;">​</a></h3><p>公共基础知识的组成比较复杂，并且有些央企的笔试内容这部分还有差异，大体是以下几门课程的集合：行测 + 申论 + 企业知识 + 时事政治 ，针对于不同国企这几类内容的考试比例，参考《央企手册》当中的文章 “笔试指南3.央国企笔试内容&amp;所占比例”，这里面会有更加全面的介绍。</p><h4 id="央国企行测-时事政治" tabindex="-1">央国企行测 &amp; 时事政治 <a class="header-anchor" href="#央国企行测-时事政治" aria-label="Permalink to &quot;央国企行测 &amp; 时事政治&quot;">​</a></h4><p>经常考公的小伙伴都知道，行测包含这几部分内容：数量关系、逻辑推理、资料分析、常识题的判断、语言的理解和表达，但是央国企的笔试并不是公务员考试，也不是专门的行测考试，对于大部分国企来说行测的内容只占有20%左右，甚至更少。</p><p>时事政治这方面，大家在刷行测的时候一起关注一下，应该问题不大，考察的也不会非常多，最多1～2道题。 所以培训结构上来就给你培训行测各种刷题技巧实际上是一种本末倒置的行为，考公可以这样弄，央国企非常不建议这样弄，这样做是本末倒置的行为。</p><h4 id="央国企申论" tabindex="-1">央国企申论 <a class="header-anchor" href="#央国企申论" aria-label="Permalink to &quot;央国企申论&quot;">​</a></h4><p>这部分内容大多数央国企的笔试是不考低，只有烟草会有30%左右的写作题，所以如果是准备央国企笔试的话，这部分不建议作为重点准备，弄2个模板就行了。</p><h4 id="企业知识" tabindex="-1">企业知识 <a class="header-anchor" href="#企业知识" aria-label="Permalink to &quot;企业知识&quot;">​</a></h4><p>中石油、电网、烟草等都是属于我们国家的垄断行业，因此这些央企在招聘的时候会考察一部分企业知识，考生需要提前了解下相关企业、行业的知识才能做对这部分题。</p><h2 id="央国企笔试重要吗" tabindex="-1">央国企笔试重要吗？ <a class="header-anchor" href="#央国企笔试重要吗" aria-label="Permalink to &quot;央国企笔试重要吗？&quot;">​</a></h2><h3 id="垄断类央企非常重要" tabindex="-1">垄断类央企非常重要 <a class="header-anchor" href="#垄断类央企非常重要" aria-label="Permalink to &quot;垄断类央企非常重要&quot;">​</a></h3><p>这个问题不是绝对的，对于烟草、电网、三桶油、中铁和国家能源这种垄断央企来说，笔试流程非常正规，笔试内容相对固定和通用，并且不卡学历。 这一类垄断央企的笔试就非常重要，很多学校/学历非常优秀的学生，不好好准备相关笔试，简历都到不了HR手里就直接把你卡掉。 所以，这类央企也相对较为公平，不看学历、学校、项目、实验室之类的，仅仅根据你的笔试成绩、面试成绩来决定你能不能进去。 当然，也会存在有那种三代烟草人的情况，但是我们还是得去试一试的，自己尽力了就没啥好遗憾的了。</p><h3 id="非垄断央企不是特别重要" tabindex="-1">非垄断央企不是特别重要 <a class="header-anchor" href="#非垄断央企不是特别重要" aria-label="Permalink to &quot;非垄断央企不是特别重要&quot;">​</a></h3><p>半垄断、非垄断央企和军工央企等，虽然有笔试但是没那么重要，如中电29所有笔试，但是考察的全部都是专业知识，只要你专业过硬其实无需特别的去准备的。 当然这类央企你去报机构，刷行测申论肯定是别想能进去了，所以大家报国企机构真不如看b站上的免费行测申论视频。 另外，还有一些工程类央企，虽然集团硬性规定必须做一个笔试，但是笔试卷子科室主任做完就丢了，看都不看。 只要你把上面填完，笔试就算你过了，其它的主要是看学历、履历、公司和项目等东西。</p>',27)])])}const m=a(n,[["render",o]]);export{d as __pageData,m as default};
